<section class="panel"><div class="panel-head"><div><h2>Record activity</h2><p>Calls, meetings, email and WhatsApp notes</p></div></div><form class="mini-form" method="post" action="<?= url('leads/'.$record['id'].'/activities') ?>"><?= csrf_field() ?><div><select name="activity_type"><option value="note">Note</option><option value="call">Call</option><option value="meeting">Meeting</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option></select><input name="subject" placeholder="Subject"></div><textarea name="details" required placeholder="Outcome, discussion and next action"></textarea><button class="button button-primary button-sm">Record activity</button></form></section>
<section class="panel"><div class="panel-head"><div><h2>Tags</h2><p>Reusable lead labels</p></div></div><div class="tag-row"><?php foreach($related['tags']??[] as $tag):?><span class="status-badge info" style="--tag-color:<?= e($tag['color']) ?>"><?= e($tag['name']) ?></span><?php endforeach;?><?php if(empty($related['tags'])):?><span class="empty-inline">No tags assigned.</span><?php endif;?></div><form class="mini-form inline-form" method="post" action="<?= url('leads/'.$record['id'].'/tags') ?>"><?= csrf_field() ?><input name="tag" maxlength="80" required placeholder="Tag name"><button class="button button-secondary button-sm">Add tag</button></form></section>
<section class="panel span-2"><div class="panel-head"><div><h2>Lead attachments</h2><p>Secure proposals, briefs and call documents</p></div></div><div class="document-list"><?php foreach($related['attachments']??[] as $file):?><a href="<?= url('lead-files/'.$file['id']) ?>"><i class="fa-solid fa-paperclip"></i><span><strong><?= e($file['title']) ?></strong><small><?= e(date('d M Y, g:i A',strtotime($file['created_at']))) ?></small></span><i class="fa-solid fa-download"></i></a><?php endforeach;?><?php if(empty($related['attachments'])):?><div class="empty-inline">No attachments uploaded.</div><?php endif;?></div><form class="mini-form inline-form" method="post" enctype="multipart/form-data" action="<?= url('leads/'.$record['id'].'/files') ?>"><?= csrf_field() ?><input name="title" required maxlength="190" placeholder="Attachment title"><input type="file" name="attachment" required accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.csv,.docx,.xlsx"><button class="button button-secondary button-sm">Upload securely</button></form></section>
